(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75)*50, 0.05, 2.4, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+3.0)*w*0.5;
  }
  const act=aS/7.45, inh=iS/7.45, cross=cS/7.45;
  const warp1 = Math.sin(sx*0.035+sy*0.02+t*0.7)*12;
  const warp2 = Math.cos(sx*0.025-sy*0.03-t*0.9)*12;
  const sx2=sx+warp1, sy2=sy+warp2;
  const bg = (Math.sin(sx2*0.04+sy2*0.025+t*0.8)+Math.sin(sx2*0.03-sy2*0.04+t*1.1))/2
    + Math.sin((sx2+sy2)*0.12+t*2.5)*0.2 + Math.sin((sx2-sy2)*0.1-t*2)*0.2
    + Math.sin(sx2*0.07+sy2*0.05+t*1.8)*0.15;
  const dist=Math.sqrt((sx2-cx)**2+(sy2-cy)**2), ang=Math.atan2(sy2-cx,sx2-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*2+t*2.1)*0.2;
  const micro = (Math.sin(sx2*0.25+t*3)*Math.sin(sy2*0.25-t*2.5)+Math.sin((sx2-sy2)*0.2+t*4)*0.5)*0.3;
  const lap = (Math.sin(sx2*0.18)*Math.cos(sy2*0.18)+Math.sin(sx2*0.12+sy2*0.12+t)*0.6)*0.4;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.3 + spiral + micro*0.2)*2.2);
  const rd2 = Math.tanh((inh - act*0.5 + cross*0.3 + lap - bg*0.2)*1.8);
  const coupling = Math.tanh((rd1*0.6 - rd2*0.4 + spiral*0.3)*2.5);
  const cell = Math.tanh((Math.sin(sx2*0.15)*Math.sin(sy2*0.15)+Math.sin((sx2+sy2)*0.1+t)*0.5)*1.5)*0.3;
  const blend = coupling*0.6 + rd1*0.2 + cell*0.2, v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[12,35,85],[18,75,120],[25,130,135],[45,170,120],
    [180,195,60],[220,150,50],[195,80,55],[150,40,70],[90,20,60],
    [40,15,55],[5,10,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(coupling*Math.PI)*0.25;
  const edge=Math.abs(coupling)>0.65?1.2:Math.abs(rd1)>0.5?1.1:1.0;
  const glow=Math.max(0, coupling*0.15);
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*180)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
